"use client"

/** @responsibility Re-exports the public surface of the SplitView component system. */

export {
  SplitView,
  type SplitViewChangeMeta,
  type SplitViewProps,
} from "./split-view"
export {
  SplitViewPanel,
  type SplitViewPanelProps,
} from "./split-view-panel"
export {
  SplitViewSeparator,
  type SplitViewSeparatorProps,
} from "./split-view-separator"
export { SplitViewOrientation } from "./split-view-options"
export {
  adjustLayoutByDelta,
  calculateDefaultLayout,
  validatePanelGroupLayout,
  type SplitViewLayout,
  type SplitViewPanelConstraints,
  type SplitViewResizeTrigger,
  type SplitViewSize,
} from "./split-view-math"
export { type SplitViewPanelSizeProps } from "./split-view-context"

"use client"

/** @responsibility Renders a controlled group of resizable panels and orchestrates pointer and keyboard resizing. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  SplitViewContext,
  composeRefs,
  sortByDocumentPosition,
  type RegisteredSplitViewPanel,
  type SplitViewContextValue,
  type SplitViewSeparatorAria,
} from "./split-view-context"
import {
  adjustLayoutByDelta,
  calculateDefaultLayout,
  calculateSeparatorAriaValues,
  layoutNumbersEqual,
  resolveSizeToPercentage,
  splitViewLayoutsEqual,
  validatePanelGroupLayout,
  type SplitViewLayout,
  type SplitViewPanelConstraints,
  type SplitViewResizeTrigger,
} from "./split-view-math"
import { SplitViewOrientation } from "./split-view-options"

/** Context accompanying every SplitView layout notification. */
interface SplitViewChangeMeta {
  /** The interaction that produced the change. */
  trigger: SplitViewResizeTrigger
}

/** State snapshotted for the lifetime of one pointer resize gesture. */
interface SplitViewDragState {
  separatorId: string
  /** The pointer that started the gesture; other pointers are ignored. */
  pointerId: number
  pivotIndices: [number, number]
  initialLayout: SplitViewLayout
  /** The most recent layout the gesture produced, committed on release. */
  latestLayout: SplitViewLayout
  startX: number
  startY: number
  groupSizePixels: number
  rightToLeft: boolean
  changed: boolean
}

/** Properties accepted by the SplitView group. */
interface SplitViewProps extends React.ComponentProps<"div"> {
  /**
   * The axis along which panels are laid out.
   * @defaultValue SplitViewOrientation.Horizontal
   */
  orientation?: SplitViewOrientation
  /**
   * Percentage layout keyed by panel id when the group is controlled by its
   * consumer. Interactions report the next layout through `onLayoutChange`;
   * the consumer renders it back through this property.
   */
  layout?: SplitViewLayout
  /** Initial percentage layout for an uncontrolled group. */
  defaultLayout?: SplitViewLayout
  /**
   * Called with the next layout on every step of an interaction, including
   * each pointer move. Persist from `onLayoutCommit` instead.
   */
  onLayoutChange?: (layout: SplitViewLayout, meta: SplitViewChangeMeta) => void
  /** Called once per settled gesture with the final layout. */
  onLayoutCommit?: (layout: SplitViewLayout, meta: SplitViewChangeMeta) => void
  /**
   * Percentage applied by one arrow-key press on a separator.
   * @defaultValue 5
   */
  keyboardResizeStep?: number
}

/**
 * Measures the group's usable extent: the sum of panel sizes along the
 * group's axis, excluding separators.
 *
 * @param panels - The registered panels in visual order.
 * @param orientation - The group's layout axis.
 * @returns The usable extent in pixels.
 */
function measureGroupSize(
  panels: readonly RegisteredSplitViewPanel[],
  orientation: SplitViewOrientation,
): number {
  return panels.reduce(
    (total, panel) =>
      total +
      (orientation === SplitViewOrientation.Horizontal
        ? panel.element.offsetWidth
        : panel.element.offsetHeight),
    0,
  )
}

/**
 * Renders a group of resizable panels separated by interactive separators.
 *
 * Compose direct children as `SplitViewPanel` and `SplitViewSeparator`
 * elements, alternating so every separator sits between two panels. The
 * group is fully controlled when `layout` is provided; state then lives with
 * the consumer and nothing is persisted internally.
 *
 * @param props - Orientation, controlled or uncontrolled layout, change
 * callbacks, and native container properties.
 * @returns A flex container coordinating its registered panels.
 */
function SplitView({
  orientation = SplitViewOrientation.Horizontal,
  layout: layoutProp,
  defaultLayout,
  onLayoutChange,
  onLayoutCommit,
  keyboardResizeStep = 5,
  className,
  children,
  ref,
  ...props
}: SplitViewProps) {
  const groupRef = React.useRef<HTMLDivElement>(null)
  // Memoized so React does not detach and re-attach refs on every render.
  const composedGroupRef = React.useMemo(
    () => composeRefs(groupRef, ref),
    [ref],
  )
  const registrationsRef = React.useRef({
    panels: new Map<string, RegisteredSplitViewPanel>(),
    separators: new Map<string, HTMLElement>(),
  })
  const [registrationVersion, setRegistrationVersion] = React.useState(0)
  const [groupSizePixels, setGroupSizePixels] = React.useState(0)
  const [internalLayout, setInternalLayout] = React.useState<
    SplitViewLayout | undefined
  >(defaultLayout)
  const [activeSeparatorId, setActiveSeparatorId] = React.useState<
    string | null
  >(null)
  const dragStateRef = React.useRef<SplitViewDragState | null>(null)
  const expandedSizesRef = React.useRef<Record<string, number>>({})

  const orderedPanels = React.useMemo(() => {
    void registrationVersion
    return sortByDocumentPosition(
      [...registrationsRef.current.panels.values()],
      (panel) => panel.element,
    )
  }, [registrationVersion])

  const orderedSeparatorIds = React.useMemo(() => {
    void registrationVersion
    return sortByDocumentPosition(
      [...registrationsRef.current.separators.entries()],
      ([, element]) => element,
    ).map(([id]) => id)
  }, [registrationVersion])

  const panelIds = React.useMemo(
    () => orderedPanels.map((panel) => panel.id),
    [orderedPanels],
  )

  const derivedConstraints = React.useMemo<SplitViewPanelConstraints[]>(() => {
    return orderedPanels.map((panel) => {
      if (groupSizePixels <= 0) {
        // A hidden or unmeasured group cannot resolve pixel constraints yet;
        // relaxed constraints keep any provided layout renderable meanwhile.
        return {
          panelId: panel.id,
          minSize: 0,
          maxSize: 100,
          collapsedSize: 0,
          collapsible: panel.constraints.collapsible === true,
          defaultSize: resolveSizeToPercentage(
            typeof panel.constraints.defaultSize === "number"
              ? panel.constraints.defaultSize
              : undefined,
            groupSizePixels,
          ),
        }
      }

      const minSize =
        resolveSizeToPercentage(panel.constraints.minSize, groupSizePixels) ?? 0
      const maxSize =
        resolveSizeToPercentage(panel.constraints.maxSize, groupSizePixels) ??
        100
      const collapsedSize =
        resolveSizeToPercentage(
          panel.constraints.collapsedSize,
          groupSizePixels,
        ) ?? 0

      return {
        panelId: panel.id,
        minSize,
        // A max written smaller than the min would be impossible; the min
        // wins and the max is raised to meet it.
        maxSize: Math.max(minSize, maxSize),
        // A collapsed size above the minimum would invert the collapse
        // snapping thresholds, so it is clamped to the minimum size.
        collapsedSize: Math.min(collapsedSize, minSize),
        collapsible: panel.constraints.collapsible === true,
        defaultSize: resolveSizeToPercentage(
          panel.constraints.defaultSize,
          groupSizePixels,
        ),
      }
    })
  }, [groupSizePixels, orderedPanels])

  const renderedLayout = React.useMemo<SplitViewLayout>(() => {
    if (panelIds.length === 0) {
      return {}
    }

    const source = layoutProp ?? internalLayout
    // The source layout is used only when it names exactly our panels with
    // usable numbers; anything else falls back to a computed default.
    const sourceMatches =
      source !== undefined &&
      panelIds.length === Object.keys(source).length &&
      panelIds.every(
        (id) =>
          typeof source[id] === "number" &&
          Number.isFinite(source[id]) &&
          source[id] >= 0,
      )

    const ordered: SplitViewLayout = {}

    if (sourceMatches) {
      for (const id of panelIds) {
        ordered[id] = source[id]
      }

      return validatePanelGroupLayout({
        layout: ordered,
        panelConstraints: derivedConstraints,
      })
    }

    return validatePanelGroupLayout({
      layout: calculateDefaultLayout(derivedConstraints),
      panelConstraints: derivedConstraints,
    })
  }, [derivedConstraints, internalLayout, layoutProp, panelIds])

  const renderedLayoutRef = React.useRef(renderedLayout)
  renderedLayoutRef.current = renderedLayout

  React.useEffect(() => {
    // The last comfortably expanded size per collapsible panel backs the
    // Enter-key collapse toggle on separators.
    for (const constraints of derivedConstraints) {
      const size = renderedLayout[constraints.panelId]

      if (
        constraints.collapsible &&
        size !== undefined &&
        !layoutNumbersEqual(size, constraints.collapsedSize)
      ) {
        expandedSizesRef.current[constraints.panelId] = size
      }
    }
  }, [derivedConstraints, renderedLayout])

  React.useEffect(() => {
    const group = groupRef.current

    if (!group || typeof ResizeObserver === "undefined") {
      return
    }

    const measure = () => {
      setGroupSizePixels(measureGroupSize(orderedPanels, orientation))
    }

    measure()

    const observer = new ResizeObserver(measure)
    observer.observe(group)

    return () => observer.disconnect()
  }, [orderedPanels, orientation])

  const applyChange = React.useCallback(
    (next: SplitViewLayout, meta: SplitViewChangeMeta) => {
      const changed = !splitViewLayoutsEqual(next, renderedLayoutRef.current)

      if (changed) {
        if (layoutProp === undefined) {
          setInternalLayout(next)
        }

        onLayoutChange?.(next, meta)
      }

      return changed
    },
    [layoutProp, onLayoutChange],
  )

  const registerPanel = React.useCallback(
    (panel: RegisteredSplitViewPanel) => {
      registrationsRef.current.panels.set(panel.id, panel)
      setRegistrationVersion((version) => version + 1)

      return () => {
        registrationsRef.current.panels.delete(panel.id)
        setRegistrationVersion((version) => version + 1)
      }
    },
    [],
  )

  const registerSeparator = React.useCallback(
    (id: string, element: HTMLElement) => {
      registrationsRef.current.separators.set(id, element)
      setRegistrationVersion((version) => version + 1)

      return () => {
        registrationsRef.current.separators.delete(id)
        setRegistrationVersion((version) => version + 1)
      }
    },
    [],
  )

  const getSeparatorPivot = React.useCallback(
    (separatorId: string): [number, number] | undefined => {
      const index = orderedSeparatorIds.indexOf(separatorId)

      if (index === -1 || index + 1 >= panelIds.length) {
        return undefined
      }

      return [index, index + 1]
    },
    [orderedSeparatorIds, panelIds],
  )

  const getSeparatorAria = React.useCallback(
    (separatorId: string): SplitViewSeparatorAria | undefined => {
      const pivot = getSeparatorPivot(separatorId)

      if (!pivot) {
        return undefined
      }

      const panelId = panelIds[pivot[0]]
      const values = calculateSeparatorAriaValues({
        layout: renderedLayout,
        panelConstraints: derivedConstraints,
        panelId,
        panelIndex: pivot[0],
      })

      return { controls: panelId, ...values }
    },
    [derivedConstraints, getSeparatorPivot, panelIds, renderedLayout],
  )

  const onSeparatorPointerDown = React.useCallback(
    (separatorId: string, event: React.PointerEvent<HTMLElement>) => {
      const pivot = getSeparatorPivot(separatorId)

      if (!pivot || event.button !== 0 || dragStateRef.current) {
        return
      }

      const group = groupRef.current
      const size = measureGroupSize(orderedPanels, orientation)

      if (!group || size <= 0) {
        return
      }

      try {
        event.currentTarget.setPointerCapture(event.pointerId)
      } catch {
        // Synthetic pointer events (tests) have no capturable pointer id;
        // resizing still works through the element's own move events.
      }

      dragStateRef.current = {
        separatorId,
        pointerId: event.pointerId,
        pivotIndices: pivot,
        initialLayout: renderedLayoutRef.current,
        latestLayout: renderedLayoutRef.current,
        startX: event.clientX,
        startY: event.clientY,
        groupSizePixels: size,
        rightToLeft: getComputedStyle(group).direction === "rtl",
        changed: false,
      }

      setActiveSeparatorId(separatorId)
    },
    [getSeparatorPivot, orderedPanels, orientation],
  )

  const onSeparatorPointerMove = React.useCallback(
    (separatorId: string, event: React.PointerEvent<HTMLElement>) => {
      const dragState = dragStateRef.current

      if (
        !dragState ||
        dragState.separatorId !== separatorId ||
        dragState.pointerId !== event.pointerId
      ) {
        return
      }

      const pixelDelta =
        orientation === SplitViewOrientation.Horizontal
          ? (event.clientX - dragState.startX) * (dragState.rightToLeft ? -1 : 1)
          : event.clientY - dragState.startY

      const next = adjustLayoutByDelta({
        delta: (pixelDelta / dragState.groupSizePixels) * 100,
        initialLayout: dragState.initialLayout,
        panelConstraints: derivedConstraints,
        pivotIndices: dragState.pivotIndices,
        prevLayout: dragState.latestLayout,
        trigger: "pointer",
      })

      dragState.latestLayout = next

      if (applyChange(next, { trigger: "pointer" })) {
        dragState.changed = true
      }
    },
    [applyChange, derivedConstraints, orientation],
  )

  const onSeparatorPointerEnd = React.useCallback(
    (separatorId: string, event: React.PointerEvent<HTMLElement>) => {
      const dragState = dragStateRef.current

      // Runs for pointer up, cancel, and lost capture; whichever arrives
      // first wins and the rest quietly do nothing.
      if (
        !dragState ||
        dragState.separatorId !== separatorId ||
        dragState.pointerId !== event.pointerId
      ) {
        return
      }

      dragStateRef.current = null
      setActiveSeparatorId(null)

      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId)
      }

      if (dragState.changed) {
        // The gesture's own latest layout is committed rather than the
        // rendered one: a controlled consumer may not have re-rendered yet.
        onLayoutCommit?.(dragState.latestLayout, { trigger: "pointer" })
      }
    },
    [onLayoutCommit],
  )

  const onSeparatorKeyDown = React.useCallback(
    (separatorId: string, event: React.KeyboardEvent<HTMLElement>) => {
      if (event.defaultPrevented) {
        return
      }

      const pivot = getSeparatorPivot(separatorId)

      if (!pivot) {
        return
      }

      const group = groupRef.current
      const rightToLeft = group
        ? getComputedStyle(group).direction === "rtl"
        : false
      const horizontal = orientation === SplitViewOrientation.Horizontal

      let delta: number | undefined

      switch (event.key) {
        case "ArrowLeft":
          if (horizontal) delta = rightToLeft ? keyboardResizeStep : -keyboardResizeStep
          break
        case "ArrowRight":
          if (horizontal) delta = rightToLeft ? -keyboardResizeStep : keyboardResizeStep
          break
        case "ArrowUp":
          if (!horizontal) delta = -keyboardResizeStep
          break
        case "ArrowDown":
          if (!horizontal) delta = keyboardResizeStep
          break
        case "Home":
          delta = -100
          break
        case "End":
          delta = 100
          break
        case "Enter": {
          const panelId = panelIds[pivot[0]]
          const constraints = derivedConstraints[pivot[0]]
          const size = renderedLayoutRef.current[panelId]

          if (constraints?.collapsible && size !== undefined) {
            delta = layoutNumbersEqual(size, constraints.collapsedSize)
              ? (expandedSizesRef.current[panelId] ?? constraints.minSize) - size
              : constraints.collapsedSize - size
          }
          break
        }
      }

      if (delta === undefined) {
        return
      }

      event.preventDefault()

      const next = adjustLayoutByDelta({
        delta,
        initialLayout: renderedLayoutRef.current,
        panelConstraints: derivedConstraints,
        pivotIndices: pivot,
        prevLayout: renderedLayoutRef.current,
        trigger: "keyboard",
      })

      if (applyChange(next, { trigger: "keyboard" })) {
        onLayoutCommit?.(next, { trigger: "keyboard" })
      }
    },
    [
      applyChange,
      derivedConstraints,
      getSeparatorPivot,
      keyboardResizeStep,
      onLayoutCommit,
      orientation,
      panelIds,
    ],
  )

  const contextValue = React.useMemo<SplitViewContextValue>(
    () => ({
      orientation,
      layout: renderedLayout,
      derivedConstraints,
      panelIds,
      activeSeparatorId,
      registerPanel,
      registerSeparator,
      getSeparatorAria,
      onSeparatorPointerDown,
      onSeparatorPointerMove,
      onSeparatorPointerEnd,
      onSeparatorKeyDown,
    }),
    [
      activeSeparatorId,
      derivedConstraints,
      getSeparatorAria,
      onSeparatorKeyDown,
      onSeparatorPointerDown,
      onSeparatorPointerEnd,
      onSeparatorPointerMove,
      orientation,
      panelIds,
      registerPanel,
      registerSeparator,
      renderedLayout,
    ],
  )

  return (
    <SplitViewContext.Provider value={contextValue}>
      {/* Consumer props spread first so the attributes the group owns
          (slot, orientation, ref) always win. */}
      <div
        {...props}
        ref={composedGroupRef}
        data-slot="split-view"
        data-orientation={orientation}
        className={cn(
          "flex h-full w-full min-h-0 min-w-0 overflow-hidden data-[orientation=vertical]:flex-col",
          className,
        )}
      >
        {children}
      </div>
    </SplitViewContext.Provider>
  )
}

export { SplitView, type SplitViewChangeMeta, type SplitViewProps }

"use client"

/** @responsibility Renders one sized panel within a SplitView and registers its element and constraints with the group. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  composeRefs,
  useSplitView,
  type SplitViewPanelSizeProps,
} from "./split-view-context"
import { layoutNumbersEqual } from "./split-view-math"

/** Properties accepted by one SplitView panel. */
interface SplitViewPanelProps
  extends Omit<React.ComponentProps<"div">, "id">,
    SplitViewPanelSizeProps {
  /**
   * Unique id of the panel within its group. Keys the group layout and is
   * rendered as the element id so separators can reference it.
   */
  id: string
}

/**
 * Renders one panel of a SplitView. The panel's size always comes from the
 * group layout; the panel itself holds no sizing state.
 *
 * @param props - The panel id, authored sizing constraints, and native
 * container properties.
 * @returns A flex child sized by the group's current layout.
 */
function SplitViewPanel({
  id,
  minSize,
  maxSize,
  defaultSize,
  collapsedSize,
  collapsible,
  className,
  style,
  children,
  ref,
  ...props
}: SplitViewPanelProps) {
  const { derivedConstraints, layout, registerPanel } = useSplitView()
  const elementRef = React.useRef<HTMLDivElement>(null)
  // Memoized so React does not detach and re-attach refs on every render.
  const composedRef = React.useMemo(() => composeRefs(elementRef, ref), [ref])

  React.useLayoutEffect(() => {
    const element = elementRef.current

    if (!element) {
      return
    }

    return registerPanel({
      id,
      element,
      constraints: { minSize, maxSize, defaultSize, collapsedSize, collapsible },
    })
  }, [
    collapsedSize,
    collapsible,
    defaultSize,
    id,
    maxSize,
    minSize,
    registerPanel,
  ])

  const size = layout[id]
  const constraints = derivedConstraints.find(
    (current) => current.panelId === id,
  )
  const collapsed =
    constraints?.collapsible === true &&
    size !== undefined &&
    layoutNumbersEqual(size, constraints.collapsedSize)

  return (
    // Consumer props spread first so the attributes the panel owns
    // (id, slot, sizing style, ref) always win.
    <div
      {...props}
      ref={composedRef}
      id={id}
      data-slot="split-view-panel"
      data-collapsed={collapsed || undefined}
      className={cn(
        "relative flex min-h-0 min-w-0 flex-col overflow-hidden",
        className,
      )}
      style={{
        ...style,
        flexBasis: 0,
        flexGrow: size ?? 1,
        flexShrink: 1,
      }}
    >
      {children}
    </div>
  )
}

export { SplitViewPanel, type SplitViewPanelProps }

"use client"

/** @responsibility Renders one accessible, keyboard-operable resize separator between two SplitView panels. */

import * as React from "react"

import { cn } from "@/lib/utils"

import { composeRefs, useSplitView } from "./split-view-context"
import { SplitViewOrientation } from "./split-view-options"

/** Properties accepted by one SplitView separator. */
interface SplitViewSeparatorProps extends React.ComponentProps<"div"> {
  /**
   * Accessible name of the separator.
   * @defaultValue "Resize panels"
   */
  "aria-label"?: string
}

/**
 * Renders the interactive separator between two adjacent SplitView panels.
 *
 * The separator implements the ARIA window-splitter pattern: it is
 * focusable, reports the reachable size range of the panel before it, and
 * resizes with arrow keys, Home, End, and Enter (collapse toggle for
 * collapsible panels). Pointer resizing uses pointer capture on the
 * separator itself.
 *
 * @param props - An optional accessible name and native element properties.
 * @returns A focusable separator element wired to its SplitView group.
 */
function SplitViewSeparator({
  "aria-label": ariaLabel = "Resize panels",
  className,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onLostPointerCapture,
  onKeyDown,
  ref,
  ...props
}: SplitViewSeparatorProps) {
  const {
    activeSeparatorId,
    getSeparatorAria,
    onSeparatorKeyDown,
    onSeparatorPointerDown,
    onSeparatorPointerEnd,
    onSeparatorPointerMove,
    orientation,
    registerSeparator,
  } = useSplitView()
  const separatorId = React.useId()
  const elementRef = React.useRef<HTMLDivElement>(null)
  // Memoized so React does not detach and re-attach refs on every render.
  const composedRef = React.useMemo(() => composeRefs(elementRef, ref), [ref])

  React.useLayoutEffect(() => {
    const element = elementRef.current

    if (!element) {
      return
    }

    return registerSeparator(separatorId, element)
  }, [registerSeparator, separatorId])

  const aria = getSeparatorAria(separatorId)
  const horizontal = orientation === SplitViewOrientation.Horizontal
  const resizing = activeSeparatorId === separatorId

  return (
    // Consumer props spread first so the accessibility attributes the
    // separator owns (role, focus, values) can never be broken from outside.
    <div
      {...props}
      ref={composedRef}
      role="separator"
      // A separator without a valid panel pair (a markup error) stays out of
      // the tab order instead of presenting an inert focusable widget.
      tabIndex={aria ? 0 : -1}
      aria-label={ariaLabel}
      aria-orientation={horizontal ? "vertical" : "horizontal"}
      aria-controls={aria?.controls}
      aria-valuenow={aria?.valueNow}
      aria-valuemin={aria?.valueMin}
      aria-valuemax={aria?.valueMax}
      data-slot="split-view-separator"
      data-orientation={orientation}
      data-resizing={resizing || undefined}
      className={cn(
        "relative z-10 shrink-0 bg-border outline-none transition-colors select-none touch-none",
        "after:absolute hover:bg-ring/60 data-resizing:bg-ring",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0",
        horizontal
          ? "w-px cursor-col-resize after:inset-y-0 after:-start-1 after:-end-1"
          : "h-px cursor-row-resize after:inset-x-0 after:-top-1 after:-bottom-1",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event)
        if (!event.defaultPrevented) onSeparatorPointerDown(separatorId, event)
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event)
        if (!event.defaultPrevented) onSeparatorPointerMove(separatorId, event)
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event)
        if (!event.defaultPrevented) onSeparatorPointerEnd(separatorId, event)
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        if (!event.defaultPrevented) onSeparatorPointerEnd(separatorId, event)
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event)
        onSeparatorPointerEnd(separatorId, event)
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) onSeparatorKeyDown(separatorId, event)
      }}
    />
  )
}

export { SplitViewSeparator, type SplitViewSeparatorProps }

"use client"

/** @responsibility Coordinates registration, layout, and interaction state between SplitView and its panels and separators. */

import * as React from "react"

import type { SplitViewOrientation } from "./split-view-options"
import type {
  SplitViewLayout,
  SplitViewPanelConstraints,
  SplitViewSize,
} from "./split-view-math"

/** Sizing constraints a panel declares in authored units. */
interface SplitViewPanelSizeProps {
  /**
   * Smallest expanded size: a percentage number, "Npx", or "N%".
   * @defaultValue 0
   */
  minSize?: SplitViewSize
  /**
   * Largest size: a percentage number, "Npx", or "N%".
   * @defaultValue 100
   */
  maxSize?: SplitViewSize
  /** Preferred initial size: a percentage number, "Npx", or "N%". */
  defaultSize?: SplitViewSize
  /**
   * Size presented while collapsed: a percentage number, "Npx", or "N%".
   * @defaultValue 0
   */
  collapsedSize?: SplitViewSize
  /**
   * Whether the panel snaps closed below its minimum size.
   * @defaultValue false
   */
  collapsible?: boolean
}

/** A panel registered with its owning SplitView. */
interface RegisteredSplitViewPanel {
  /** The panel's unique id within the group. */
  id: string
  /** The panel's rendered element, used for ordering and measurement. */
  element: HTMLElement
  /** The panel's authored sizing constraints. */
  constraints: SplitViewPanelSizeProps
}

/** ARIA values presented by one separator. */
interface SplitViewSeparatorAria {
  /** The id of the panel the separator controls. */
  controls: string
  /** The controlled panel's current percentage size. */
  valueNow: number | undefined
  /** The smallest reachable percentage size. */
  valueMin: number
  /** The largest reachable percentage size. */
  valueMax: number
}

/** Shared state and interaction handlers provided by one SplitView. */
interface SplitViewContextValue {
  /** The axis along which the group lays out its panels. */
  orientation: SplitViewOrientation
  /** The validated layout currently rendered, keyed by panel id. */
  layout: SplitViewLayout
  /** Percentage-resolved constraints, in panel order. */
  derivedConstraints: readonly SplitViewPanelConstraints[]
  /** Panel ids in visual order. */
  panelIds: readonly string[]
  /** The separator currently driving a pointer resize, if any. */
  activeSeparatorId: string | null
  /** Registers a panel; returns its disposer. */
  registerPanel: (panel: RegisteredSplitViewPanel) => () => void
  /** Registers a separator element; returns its disposer. */
  registerSeparator: (id: string, element: HTMLElement) => () => void
  /** Computes the ARIA values for a registered separator. */
  getSeparatorAria: (separatorId: string) => SplitViewSeparatorAria | undefined
  /** Begins a pointer-driven resize from a separator. */
  onSeparatorPointerDown: (
    separatorId: string,
    event: React.PointerEvent<HTMLElement>,
  ) => void
  /** Continues an active pointer-driven resize. */
  onSeparatorPointerMove: (
    separatorId: string,
    event: React.PointerEvent<HTMLElement>,
  ) => void
  /** Settles or cancels an active pointer-driven resize. */
  onSeparatorPointerEnd: (
    separatorId: string,
    event: React.PointerEvent<HTMLElement>,
  ) => void
  /** Applies keyboard resize commands from a separator. */
  onSeparatorKeyDown: (
    separatorId: string,
    event: React.KeyboardEvent<HTMLElement>,
  ) => void
}

const SplitViewContext = React.createContext<SplitViewContextValue | null>(null)

/**
 * Reads the coordination state of the nearest SplitView.
 *
 * @returns The current SplitView context value.
 * @throws When called outside a SplitView.
 */
function useSplitView(): SplitViewContextValue {
  const context = React.useContext(SplitViewContext)

  if (!context) {
    throw new Error(
      "SplitView panels and separators must be used within a SplitView.",
    )
  }

  return context
}

/**
 * Builds one ref callback that feeds an element to our internal ref and to
 * a ref the consumer may have passed, so neither side loses it.
 *
 * @param internal - The component's own element ref.
 * @param forwarded - The consumer's ref, if any.
 * @returns A ref callback serving both.
 */
function composeRefs<Element>(
  internal: React.RefObject<Element | null>,
  forwarded: React.Ref<Element> | undefined,
): React.RefCallback<Element> {
  return (element) => {
    internal.current = element

    if (typeof forwarded === "function") {
      forwarded(element)
    } else if (forwarded) {
      forwarded.current = element
    }
  }
}

/**
 * Orders registered elements by their position in the document, so panel and
 * separator order always matches what the user sees regardless of mount
 * order.
 *
 * @param entries - The registered entries to order.
 * @param getElement - Reads the element from one entry.
 * @returns The entries sorted in document order.
 */
function sortByDocumentPosition<Entry>(
  entries: readonly Entry[],
  getElement: (entry: Entry) => HTMLElement,
): Entry[] {
  return [...entries].sort((a, b) => {
    const position = getElement(a).compareDocumentPosition(getElement(b))

    if (position & Node.DOCUMENT_POSITION_FOLLOWING) return -1
    if (position & Node.DOCUMENT_POSITION_PRECEDING) return 1
    return 0
  })
}

